<?php declare(strict_types=1); require_once dirname(__DIR__).'/config.php';require_once dirname(__DIR__).'/lib/common.php';tp_admin_required();$pdo=tp_db();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action']??'';if($a==='cargo'){$id=(int)$_POST['id'];$cnt=(int)($_POST['vehicle_count']??0);$kg=(float)($_POST['total_weight_kg']??0);$guess=trim($_POST['model_guess']??'')?:tp_model_guess($cnt,$kg);$pdo->prepare('UPDATE tp_vessels SET tesla_flag=1,vehicle_count=?,total_weight_kg=?,model_guess=?,cargo_status=? WHERE id=?')->execute([$cnt?:null,$kg?:null,$guess,trim($_POST['cargo_status']??''),$id]);}elseif($a==='sub'){$pdo->prepare('INSERT INTO tp_subscribers(name,phone) VALUES(?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),is_active=1')->execute([trim($_POST['name']),preg_replace('/\D/','',$_POST['phone'])]);}header('Location:index.php');exit;}
$rows=$pdo->query('SELECT * FROM tp_vessels ORDER BY COALESCE(eta,first_seen_at) DESC LIMIT 100')->fetchAll();$subs=$pdo->query('SELECT * FROM tp_subscribers ORDER BY id DESC')->fetchAll(); ?>
