<?php foreach($rows as $r):?><div class="card shadow-sm mb-3 <?= $r['tesla_flag']?'tesla':''?>"><div class="card-body"><div class="d-flex justify-content-between"><div><b><?=h($r['vessel_name'])?></b> <span class="badge text-bg-light"><?=h($r['voyage_no'])?></span></div><div><?=h($r['eta'])?></div></div><div class="small text-secondary my-2"><?=h($r['origin_port'])?> → <?=h($r['port_name'])?></div><?php if($r['tesla_flag']):?><div class="alert alert-dark py-2">TESLA · <?=h($r['vehicle_count'])?>대 · <?=h($r['model_guess'])?> · <?=h($r['cargo_status'])?> <?= $r['notified_at']?'· 알림완료':''?></div><?php endif?><form method="post" class="row g-2"><input type="hidden" name="action" value="cargo"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="col-3"><input class="form-control" name="vehicle_count" type="number" placeholder="차량수" value="<?=h($r['vehicle_count'])?>"></div><div class="col-3"><input class="form-control" name="total_weight_kg" type="number" step="0.01" placeholder="총중량 kg" value="<?=h($r['total_weight_kg'])?>"></div><div class="col-3"><input class="form-control" name="model_guess" placeholder="모델(빈칸=자동추정)" value="<?=h($r['model_guess'])?>"></div><div class="col-2"><input class="form-control" name="cargo_status" placeholder="상태" value="<?=h($r['cargo_status'])?>"></div><div class="col-1"><button class="btn btn-outline-dark w-100">✓</button></div></form></div></div><?php endforeach?></div><div style="max-width:1100px;margin:20px auto"><a href="iopr_test.php">관세청 API024 입출항보고 테스트</a></div></body></html>
